<?php
namespace App\Services; use App\Core\Database; final class KnowledgeService { public function sources(int $serviceId):array{$s=Database::pdo()->prepare('SELECT * FROM knowledge_sources WHERE service_id=? ORDER BY authority_level,verified_at DESC');$s->execute([$serviceId]);return $s->fetchAll();} public function add(array $d):int{$s=Database::pdo()->prepare('INSERT INTO knowledge_sources(service_id,title,url,authority_level,discovered_at,verified_at,effective_date,review_date,confidence,requirement_text) VALUES(?,?,?,?,NOW(),?,?,?,?,?)');$s->execute([$d['service_id']??null,$d['title'],$d['url'],$d['authority_level']??'official',$d['verified_at']??null,$d['effective_date']??null,$d['review_date']??null,$d['confidence']??'medium',$d['requirement_text']??null]);return (int)Database::pdo()->lastInsertId();}}
